/** Serials minted as GEN-… are regenerated by the equipment sheet and cannot be keys. */

export function isUnstableSerial(serial: string | null | undefined): boolean {
  return /^gen-/i.test((serial ?? "").trim());
}

export function normalizeKey(value: string | null | undefined): string {
  return (value ?? "").replace(/\s+/g, " ").trim().toLowerCase();
}

/**
 * Stable match for an unstable serial: site, sheet sequence, name, category, supplier reference.
 * Captured from the sheet. Local edits do not rewrite it, or the next pull would miss the row.
 */
export function matchFingerprint(input: {
  siteId: string;
  siteSeq: number | string;
  name: string;
  category: string;
  supplierReference?: string | null;
}): string {
  return [
    normalizeKey(input.siteId),
    String(input.siteSeq ?? "").trim(),
    normalizeKey(input.name),
    normalizeKey(input.category),
    normalizeKey(input.supplierReference),
  ].join("|");
}

export function fingerprintFromCells(cells: Record<string, string>): string {
  return matchFingerprint({
    siteId: cells["ID"] ?? "",
    siteSeq: cells["idnum"] ?? "",
    name: cells["Nombre del equipo"] ?? "",
    category: cells["Categoría del equipo"] ?? "",
    supplierReference: cells["Referencia de Proveedor"] ?? "",
  });
}

/** Company-wide stable id. Independent of the sheet serial. */
export function internalIdFor(sequence: number): string {
  return `EQ-${String(sequence).padStart(4, "0")}`;
}

export const INTERNAL_ID_HEADER = "ID interno";
